edit(6,'The Decision at Home',{start:30,place:'Green Gables yard',notes:{'Anne Shirley':'Returns still unsure of the adults’ decision.','Marilla Cuthbert':'Agrees with Matthew to keep Anne but delays telling her.','Matthew Cuthbert':'Welcomes the agreement and urges kindness toward the girl.'}});
edit(8,'Waiting for Marilla’s Answer',{description:'After testing Anne through household work, Marilla tells her she may remain at Green Gables.',notes:{'Anne Shirley':'Pleads for an answer and cries with relief when told she may stay.','Marilla Cuthbert':'Announces that Anne may stay and requires prompt obedience.'}});
