edit(8,'Rules for a New Life',{place:'Green Gables parlour',description:'Marilla finds Anne absorbed in a religious picture and directs her to learn the Lord’s Prayer.',notes:{'Anne Shirley':'Imagines herself in the picture and takes up the prayer card.','Marilla Cuthbert':'Checks Anne’s irreverent-sounding interpretation and assigns the prayer.'}});
edit(8,'The Prospect of a Bosom Friend',{start:35,place:'Green Gables parlour'});
add(8,s(54,'Friends in the Window','East gable','Anne learns the prayer and greets the trees from her window.','A:Finishes the prayer lesson and returns to companionable daydreams.'));
edit(17,'Anne Chooses School Again',{start:15});edit(17,'Lessons as Refuge',{start:21});
add(17,s(24,'School’s Welcome Is Reported','Green Gables kitchen','Anne tells Marilla that she has been welcomed back.','A:Finds comfort in classmates’ tokens of appreciation.|M:Hears about the warm welcome.'));
add(17,s(25,'Gifts Across the Classroom','Avonlea school','Gilbert leaves a candy heart, and Anne and Diana exchange letters despite their separation.','A:Rejects Gilbert’s gift but treasures Diana’s letter.|G:Leaves a candy heart at Anne’s desk.|D:Sends Anne a letter explaining her mother’s prohibition.|H:Keeps Anne among the girls rather than beside Gilbert.'));
add(17,s(38,'Determination and Geometry','Green Gables kitchen','Anne’s determined schoolwork brings progress, though geometry remains a struggle.','A:Works hard and complains about geometry.|M:Watches Anne persist with her lessons.'));
edit(19,'A Night at Orchard Slope',{start:35});edit(19,'Miss Barry Is Startled',{start:42});
edit(19,'The News at Green Gables',{start:59,notes:{'Anne Shirley':'Accepts blame for suggesting the leap into bed.','Rachel Lynde':'Reports Aunt Josephine’s anger and counsels thinking before acting.'}});
add(19,s(68,'Diana’s Fear for the Lessons','Orchard Slope','Diana fears her aunt’s anger will cost her music lessons; Anne decides to apologize.','A:Resolves to face Aunt Josephine despite fear.|D:Explains her aunt’s anger and tries to dissuade Anne.'));
edit(19,'A Confession in the Spare Room',{start:77,notes:{'Anne Shirley':'Explains the accident and asks Aunt Josephine to understand the girls’ disappointment.','Josephine Barry':'Laughs at Anne’s argument and promises to continue the lessons.'}});
add(19,s(94,'The New Friend Is Discussed','Green Gables kitchen','Anne reports the unexpected friendship with Aunt Josephine.','A:Explains that the stern visitor proved a kindred spirit.|M:Remarks that she had expected Anne to charm the visitor.|T:Hears Marilla’s comment on the successful apology.'));
edit(20,'Spring at Green Gables',{place:'Green Gables kitchen'});edit(20,'The Haunted Wood',{start:6,place:'East gable'});
edit(20,'The Wood Must Be Crossed',{start:35,notes:{'Anne Shirley':'Crosses the terrifying path alone and regrets inventing ghosts.'}});
add(20,s(36,'The Errand Is Finished','Green Gables kitchen','Anne returns shaken but unharmed and promises to be content with ordinary places.','A:Admits the fright her invention caused.|M:Points out that nothing caught Anne.'));
edit(21,'A New Minister',{place:'Green Gables kitchen',description:'Anne reports Mr. Phillips’s departure and discusses the candidates for Avonlea’s ministry.',notes:{'Anne Shirley':'Returns from the teacher’s farewell in tears and comments on the new ministerial candidates.','Marilla Cuthbert':'Questions Anne’s grief and listens to her judgments.','Matthew Cuthbert':'Hears Anne’s opinion of the candidates.'}});
edit(24,'Miss Stacy’s Plans',{place:'Avonlea school',description:'Anne returns after her ankle heals and finds a sympathetic new teacher.',notes:{'Anne Shirley':'Resumes school in October after the long recovery.','Miss Stacy':'Welcomes the pupils and guides recitations, fieldwork and exercises.'}});
add(24,s(3,'The New School Methods at Home','Green Gables kitchen','Anne explains Miss Stacy’s recitations and outdoor lessons to the Cuthberts.','A:Defends the new teacher’s lively methods.|M:Questions whether the exercises are sensible.|T:Offers to hear Anne’s recitation.'));
edit(21,'Mrs. Allan at Avonlea',{place:'Green Gables kitchen'});edit(21,'Preparing for Tea',{start:16,notes:{'Anne Shirley':'Plans the cake and describes her preparations to Diana.','Marilla Cuthbert':'Prepares the tea and agrees to let Anne decorate.','Diana Barry':'Hears Anne’s anxious plans for the cake.'}});
