add(28,s(37,'The Girls Find Anne Safe','Barry pond bridge','Jane and Diana return frantic and learn how Anne escaped.','A:Explains that Gilbert brought her ashore.|D:Embraces Anne with relief.|J:Calls Gilbert’s rescue romantic.'));
edit(29,'The Best Part of the Visit',{start:36});edit(30,'The Queen’s Group Studies',{start:28});
add(30,s(38,'Rachel Assesses Anne’s Growth','Green Gables parlour','Rachel visits after Matthew’s heart trouble and comments on Anne’s growing competence.','M:Explains the heart attack that kept her from the meeting.|R:Praises Anne’s cooking and the change in her manners.|A:Prepares tea and biscuits for the visitor.'));
edit(31,'A Last Free Summer',{notes:{'Anne Shirley':'Enjoys outdoor holidays instead of reading.','Diana Barry':'Shares the summer’s woodland adventures.'}});
add(31,s(4,'Books and a New Dress','Green Gables kitchen','Anne resumes her books and talks with Marilla about independence and a new dress.','A:Welcomes her books after the holiday and confides her mixed feelings toward Rachel.|M:Shares some of Anne’s reservations and notices her maturity.'));
edit(31,'The Queen’s Class at Work',{start:11});edit(31,'Marilla Faces the Coming Change',{start:16,notes:{'Anne Shirley':'Has grown taller than Marilla.','Marilla Cuthbert':'Measures Anne’s height and mourns the approaching departure.','Matthew Cuthbert':'Points out that the new railway will make home visits possible.'}});edit(31,'The Spring Before Entrance',{start:21});
edit(32,'Entrance Week',{start:14,place:'Beechwood',title:'A Letter from Entrance Week',description:'Writing from Beechwood, Anne tells Diana about the entrance papers, her nerves and the other candidates.',notes:{'Anne Shirley':'Writes to Diana after the first examination day and recounts events at Queen’s.'}});
edit(32,'Waiting for the Pass List',{start:25,notes:{'Anne Shirley':'Returns from the examinations with uncertainty about geometry.','Diana Barry':'Welcomes Anne home and asks how the papers went.'}});
edit(32,'The Pass List',{start:38,place:'East gable',notes:{'Anne Shirley':'Reads the published list and realizes she tied with Gilbert for first place.','Diana Barry':'Runs upstairs with the newspaper and congratulates Anne.'}});
add(32,s(44,'The Household Hears the Results','Green Gables yard','Anne and Diana take the result to the hayfield, where the Cuthberts and Rachel celebrate.','A:Brings the paper to Matthew and Marilla.|D:Accompanies Anne with the news.|T:Examines the list delightedly.|M:Tries to conceal her pride.|R:Praises Anne openly.'));
add(32,s(49,'Thankfulness Before Sleep','East gable','Anne ends the evening with a grateful prayer at her window.','A:Prays with gratitude for the past and hope for the future.'));
edit(33,'Diana’s Finishing Touches',{notes:{'Anne Shirley':'Accepts Diana’s judgment of the pearl beads.','Diana Barry':'Finishes Anne’s outfit and admires its effect.','Marilla Cuthbert':'Checks that Anne looks neat and worries about the damp drive.'}});
edit(33,'The Hotel Audience',{start:29,notes:{'Anne Shirley':'Rides to White Sands and feels intimidated by the richly dressed company.','Diana Barry':'Travels with Anne and takes her place in the audience.','Jane Andrews':'Joins the trip to the hotel concert.'}});
edit(33,'Anne’s Recitation',{notes:{'Anne Shirley':'Overcomes stage fright when she sees Gilbert and recites with new determination.','Diana Barry':'Hears Anne win the audience’s applause.','Jane Andrews':'Watches Anne’s successful performance.','Gilbert Blythe':'Listens from the back of the room with a smile that Anne reads as a challenge.'}});
edit(37,'Matthew Falls',{description:'Matthew collapses as Anne comes in with flowers, and Marilla calls for help.',notes:{'Anne Shirley':'Finds Matthew collapsed and runs to summon the hired man.','Marilla Cuthbert':'Calls urgently for assistance.','Matthew Cuthbert':'Lies motionless after collapsing; no medical assessment has yet been made.'}});
add(37,s(4,'Martin Fetches Medical Help','Orchard Slope','Martin goes for the doctor and calls at Orchard Slope to send the Barrys and Rachel to the farm.','Z:Leaves for medical help and calls at the Barry household on his way.|R:Is visiting Orchard Slope when Martin calls and goes to help the Cuthberts.',4));
add(37,s(5,'Rachel Checks Matthew’s Heart','Green Gables kitchen','Rachel examines Matthew and tells Anne and Marilla that nothing can be done.','A:Is unable to say the dreadful word and looks at Matthew’s still face.|M:Faces Rachel’s grave assessment.|T:Lies dead after the sudden collapse.|R:Checks the pulse and heart and recognizes death.',5));
edit(37,'The Doctor Confirms the Death',{notes:{'Anne Shirley':'Hears that Matthew died instantly and probably without pain.','Marilla Cuthbert':'Receives the medical confirmation while grieving.','Matthew Cuthbert':'His sudden death is medically confirmed.','The doctor at Green Gables':'Explains that the shock probably caused heart failure.','Rachel Lynde':'Helps the bereaved household as neighbors gather.'}});
add(33,s(41,'The Drive from White Sands','White Sands','The girls discuss jewels, the concert and the wealth of youth on their way home.','A:Affirms her contentment with her own life and Matthew’s beads.|D:Reports a compliment about Anne’s hair.|J:Longs for the hotel visitors’ diamonds.'));
for(const [ch,rows] of sceneModel){rows.sort((a,b)=>a.start-b.start);if(new Set(rows.map(r=>r.start)).size!==rows.length)throw Error(`Duplicate cut ${ch}`)}

// Chapter 29 quotes Anne's later account within the Exhibition passage, then
// resumes Friday's departure. Retain the quotation in that visit's scene;
// Marilla is its addressee, not a body at the Exhibition. A separate farm
// reporting event here would falsely send Anne home and back to town.
sceneModel.set(29,sceneModel.get(29).filter(r=>r.title!=='The City Visit Is Recounted'));
edit(29,'The Exhibition',{description:'Aunt Josephine takes the girls to the Exhibition; the narrator includes Anne’s later account of its sights and the evening concert.',notes:{'Anne Shirley':'Visits the exhibits and races; her quoted account records their impressions.','Diana Barry':'Shares the Exhibition visit and the city amusements Anne describes.','Josephine Barry':'Hosts the girls and takes them to the Exhibition.'}});

for(const title of ['Rachel Checks Matthew’s Heart','The Doctor Confirms the Death']){
 const row=sceneModel.get(37).find(r=>r.title===title);
 row.notes['Mr. Barry']=title==='Rachel Checks Matthew’s Heart'?'Comes from Orchard Slope with his wife and Rachel to help the distressed household.':'Remains with the bereaved Cuthberts as neighbors bring help.';
 row.notes['Mrs. Barry']=title==='Rachel Checks Matthew’s Heart'?'Joins her husband and Rachel at Green Gables after Martin’s summons.':'Helps the Cuthbert household through the day of mourning.';
}
add(37,s(12,'Matthew’s Coffin in the Parlour','Green Gables parlour','As night falls, Anne brings Matthew the garden flowers he quietly loved.','A:Gathers familiar flowers for Matthew and brings them to his coffin.|T:Lies in his coffin in the quiet parlour.',4));
